package com.cyancoder.report.service;import com.cyancoder.report.entity.PlatformHealthRunEntity;import com.cyancoder.report.repository.PlatformHealthRunRepository;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.cloud.client.discovery.DiscoveryClient;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;@Service public class PlatformHealthHistoryService{private final PlatformHealthRunRepository runs;private final DiscoveryClient discovery;private final TenantMembershipClient memberships;private final ObjectMapper json;private final List<String> services;public PlatformHealthHistoryService(PlatformHealthRunRepository r,DiscoveryClient d,TenantMembershipClient m,ObjectMapper j,@Value("${platform.health.service-keys:ai-orchestrator-service,automation-orchestrator-service,bpm-service,media-service,report-service,storefront-service,tenant-service,notification-service,bot-adapter-service}")List<String>s){runs=r;discovery=d;memberships=m;json=j;services=s;}
 public HealthRunView run(String tenant,String site,String actor){memberships.requireMembership(tenant,actor);Instant start=Instant.now();List<HealthCheckView> checks=services.stream().distinct().map(key->{long begin=System.nanoTime();boolean available=!discovery.getInstances(key).isEmpty();return new HealthCheckView(key,available?"AVAILABLE":"UNAVAILABLE",available?"Service route is registered":"No service instance is registered",(System.nanoTime()-begin)/1_000_000);}).toList();PlatformHealthRunEntity e=new PlatformHealthRunEntity();e.setRunId(UUID.randomUUID().toString());e.setTenantKey(tenant);e.setSiteKey(blank(site));e.setActor(actor);e.setStatus(checks.stream().allMatch(c->"AVAILABLE".equals(c.status()))?"HEALTHY":checks.stream().noneMatch(c->"AVAILABLE".equals(c.status()))?"UNAVAILABLE":"DEGRADED");e.setChecksJson(write(checks));e.setCreatedAt(start);e.setCompletedAt(Instant.now());return view(runs.save(e));}
 public HealthRunPage history(String tenant,String site,String actor,int page,int size){memberships.requireMembership(tenant,actor);Page<PlatformHealthRunEntity> p=runs.findByTenantKeyAndSiteKey(tenant,blank(site),PageRequest.of(Math.max(0,page),Math.max(1,Math.min(size,100)),Sort.by(Sort.Direction.DESC,"createdAt")));return new HealthRunPage(p.getContent().stream().map(this::view).toList(),p.getNumber(),p.getSize(),p.getTotalElements());}private HealthRunView view(PlatformHealthRunEntity e){return new HealthRunView(e.getRunId(),e.getStatus(),read(e.getChecksJson()),e.getCreatedAt(),e.getCompletedAt());}private String write(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException(e);}}private List<HealthCheckView>read(String v){try{return json.readValue(v,new TypeReference<>(){});}catch(Exception e){return List.of();}}private String blank(String v){return v==null||v.isBlank()?null:v;}public record HealthCheckView(String serviceKey,String status,String detail,long durationMs){}public record HealthRunView(String runId,String status,List<HealthCheckView>checks,Instant createdAt,Instant completedAt){}public record HealthRunPage(List<HealthRunView>items,int page,int size,long total){}
}
